import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Arquitectura — Diseñar para el cambio","description":"De servicios de un archivo a sistemas distribuidos — modularidad, dominios de fallo y la evolución como preocupación de primera clase.","frontmatter":{"title":"Arquitectura — Diseñar para el cambio","description":"De servicios de un archivo a sistemas distribuidos — modularidad, dominios de fallo y la evolución como preocupación de primera clase."},"headers":[],"relativePath":"es/skills/architecture/index.md","filePath":"es/skills/architecture/index.md"}`),a={name:`es/skills/architecture/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="arquitectura-—-disenar-para-el-cambio" tabindex="-1">Arquitectura — Diseñar para el cambio <a class="header-anchor" href="#arquitectura-—-disenar-para-el-cambio" aria-label="Permalink to “Arquitectura — Diseñar para el cambio”">​</a></h1><p>La arquitectura es el conjunto de decisiones caras de cambiar después. Mi sesgo: empezar tan pequeño como sea posible — a veces <a href="/Usf/es/projects/glm-free-api/">un solo archivo</a> — pero con costuras en los lugares correctos, para que crecer signifique reemplazar módulos en vez de reescribir sistemas.</p><h2 id="principios-con-los-que-diseno" tabindex="-1">Principios con los que diseño <a class="header-anchor" href="#principios-con-los-que-diseno" aria-label="Permalink to “Principios con los que diseño”">​</a></h2><ul><li><strong>Dominios de fallo.</strong> Lo que puede morir debe morir solo — los routers aíslan proveedores, los paneles aíslan usuarios.</li><li><strong>Tecnología aburrida primero.</strong> El presupuesto de innovación se gasta en la única cosa que es realmente nueva.</li><li><strong>Interfaces sobre implementaciones.</strong> La forma de la API de OpenAI se volvió estándar precisamente porque los contratos viven más que los productos.</li><li><strong>El estado es la parte difícil.</strong> Mantenlo pequeño, explícito, con backup, y sabe dónde vive cada byte.</li><li><strong>Rutas de evolución.</strong> Cada diseño lleva una nota de &quot;cuando esto se le quede pequeño&quot; — escrita mientras los trade-offs están frescos.</li></ul><p>La cartera de proyectos sigue este mismo arco: los puentes (<a href="/Usf/es/projects/glm-free-api/">un archivo</a>) maduraron a routers (<a href="/Usf/es/projects/omnirouter/">OmniRouter</a>), los routers a stacks (<a href="/Usf/es/projects/hermes-stack/">Hermes</a>) — cada paso reemplazó un módulo, no reescribió un sistema. Eso es para mí lo que significa &quot;ingeniero versátil&quot;: no saberlo todo, sino construir de forma que puedas aprender lo siguiente.</p>`,5)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};